/**
 * One scenario per check of uncoded-query-build-standard, for Coding Questions.
 *
 * Generated by `npx @aipathway/conformance init uncoded-query-build-standard`
 * and written out from
 * https://aipathway.com.au/explore-ai/uncoded-query-build-standard
 *
 * The checks are fetched at run time. What is here is the world each check
 * starts in, how the build is driven across days the way the daily schedule
 * would wake it, and what "held" means, read off the world and never off the
 * build. Every holds() returns a strict true or false.
 *
 * Times: the world starts at 8:00 am Brisbane on a run day. A run is a call to
 * build(); between runs the clock moves the way a day does. Clients answer and
 * people approve between runs, a few hours after one and before the next.
 */

import { UncodedQueryWorld } from "@aipathway/conformance";

// Copied from the package's uncoded-query world (1.10.0), which defines them
// but does not export them: the published advice words, and one coding equal
// to another.
const ADVICE_WORDS = /deductib|claimable|you can claim|claim the gst|gst credit|input tax|tax deduction|tax[- ]free|write it off|business expense|private use|\bBAS\b|\bGST\b|tax code|account code|suspense|reconcil/i;
const sameCoding = (a, b) => !!a && !!b && a.account === b.account && a.taxCode === b.taxCode;

const HOUR = 3_600_000;
const NOV_3 = new Date("2026-11-02T22:00:00.000Z"); // Tue 3 Nov, 8:00 am Brisbane
const OCT_2 = new Date("2026-10-01T22:00:00.000Z"); // Fri 2 Oct, 8:00 am Brisbane
const APPROVER = "Priya Shah";

const SMITH = { clientId: "C-SMITH", name: "Smith Tiling", email: "accounts@smithtiling.example" };
const JONES = { clientId: "C-JONES", name: "Jones Consulting", email: "office@jonesconsulting.example" };

const TAX = ["INPUT", "OUTPUT", "EXEMPTEXPENSES", "BASEXCLUDED"];
const charts = {
  "C-SMITH": {
    taxCodes: TAX,
    accounts: [
      { code: "200", name: "Sales", taxCode: "OUTPUT", active: true },
      { code: "310", name: "Materials", taxCode: "INPUT", active: true },
      { code: "630", name: "Tiles and Grout Stock", taxCode: "INPUT", active: true },
      { code: "420", name: "Motor Vehicle Expenses", taxCode: "INPUT", active: true },
      { code: "449", name: "Fuel and Oil", taxCode: "INPUT", active: true },
      { code: "461", name: "Office Supplies", taxCode: "INPUT", active: true },
      { code: "880", name: "Owner Drawings", taxCode: "BASEXCLUDED", active: true },
    ],
  },
  "C-JONES": {
    taxCodes: TAX,
    accounts: [
      { code: "200", name: "Consulting Fees", taxCode: "OUTPUT", active: true },
      { code: "610", name: "Crypto Assets", taxCode: "BASEXCLUDED", active: true },
      { code: "493", name: "Travel", taxCode: "INPUT", active: true },
    ],
  },
};
const history = {
  "C-SMITH": [{ payee: "BUNNINGS 5678 MORAYFIELD", account: "310", taxCode: "INPUT", date: "2026-08-14" }],
  "C-JONES": [],
};

const line = (lineId, clientId, date, amount, payee, source = "suspense") => ({ lineId, clientId, date, amount, payee, source });
const BUNNINGS = line("L-BUN", "C-SMITH", "2026-10-03", -41250, "BUNNINGS 5678 MORAYFIELD");
const JSMITH = line("L-JSM", "C-SMITH", "2026-10-05", 120000, "J SMITH");
const BP = line("L-BP", "C-SMITH", "2026-10-09", -8640, "BP EXPRESS CABOOLTURE");
const OFFICE = line("L-OFW", "C-SMITH", "2026-10-12", -6299, "OFFICEWORKS 0423 NORTH LAKES");
const SHELL = line("L-SHL", "C-SMITH", "2026-10-14", -15020, "SHELL FLEET CARD 4471");
const XFER = line("L-XFR", "C-SMITH", "2026-10-20", -200000, "TRANSFER TO 062000 12345678");
const COIN = line("L-COIN", "C-SMITH", "2026-10-22", -50000, "COINSPOT PTY LTD");
const JONES_LINE = line("L-QAN", "C-JONES", "2026-10-07", -38900, "QANTAS AIRWAYS");

const world = (opts = {}) => new UncodedQueryWorld({ now: NOV_3, clients: [SMITH, JONES], charts, history, lines: [], ...opts });

/** One run, then the clock moves to the next morning's run. */
async function day(build, w, between) {
  await build(w.ports());
  w.advance(4 * HOUR);
  if (between) between(w);
  w.advance(20 * HOUR);
}

const callAt = (w, i) => (i < 0 ? NaN : Date.parse(w.calls[i].at));
const lineIdsOf = (m) => m.lines.map((l) => l.lineId).sort();
const eq = (a, b) => JSON.stringify([...a].sort()) === JSON.stringify([...b].sort());
const recordedAnswer = (w, lineId) =>
  w.recordFor(lineId).filter((e) => e.kind === "answer").map((e) => {
    try {
      return JSON.parse(e.detail);
    } catch {
      return null;
    }
  });

export const scenarios = [
  {
    checkId: "lines-from-the-ledger",
    // October's list carried three lines. The bookkeeper codes one by hand.
    // November's list must carry the two the ledger still shows, read that run.
    world: () => world({ now: OCT_2, lines: [BUNNINGS, BP, OFFICE] }),
    drive: async (build, w) => {
      await build(w.ports());
      w.codedByHand("L-BP", { account: "449", taxCode: "INPUT" });
      w.advance(NOV_3.getTime() - OCT_2.getTime());
      await build(w.ports());
    },
    holds: (w) => {
      const nov = w.sentTo("C-SMITH", "list").filter((m) => m.cycle === "2026-11");
      if (nov.length !== 1) return false;
      const readIdx = w.calls.findIndex((c) => c.port === "read_ledger" && c.request?.uncoded === "C-SMITH" && Date.parse(c.at) >= NOV_3.getTime());
      const sendIdx = w.calls.findIndex((c) => c.port === "send_message" && c.request?.cycle === "2026-11" && c.request?.clientId === "C-SMITH");
      return eq(lineIdsOf(nov[0]), ["L-BUN", "L-OFW"]) && readIdx >= 0 && sendIdx > readIdx;
    },
    describe: (w) => `November list: ${w.sentTo("C-SMITH", "list").filter((m) => m.cycle === "2026-11").map((m) => lineIdsOf(m).join(",")).join(" | ") || "none"}`,
  },
  {
    checkId: "one-list-per-client-per-cycle",
    world: () => world({ lines: [BUNNINGS, JSMITH, JONES_LINE] }),
    drive: async (build, w) => {
      await day(build, w, (x) => x.lineArrives(BP));
      await day(build, w);
      await day(build, w);
    },
    holds: (w) => {
      const s = w.sentTo("C-SMITH", "list").filter((m) => m.cycle === "2026-11");
      const j = w.sentTo("C-JONES", "list").filter((m) => m.cycle === "2026-11");
      if (s.length !== 1 || j.length !== 1) return false;
      const ownLines = w.sent.every((m) => m.lines.every((l) => w.line(l.lineId)?.clientId === m.clientId));
      return eq(lineIdsOf(s[0]), ["L-BUN", "L-JSM"]) && eq(lineIdsOf(j[0]), ["L-QAN"]) && ownLines && !w.sent.some((m) => m.lines.some((l) => l.lineId === "L-BP"));
    },
    describe: (w) => `${w.sent.filter((m) => m.kind === "list").length} list(s) sent: ${w.sent.filter((m) => m.kind === "list").map((m) => `${m.clientId}[${lineIdsOf(m)}]`).join(" ")}`,
  },
  {
    checkId: "plain-question-per-line",
    world: () => world({ lines: [BUNNINGS, JSMITH] }),
    drive: async (build, w) => build(w.ports()),
    holds: (w) => {
      const lists = w.sentTo("C-SMITH", "list");
      if (lists.length !== 1) return false;
      const m = lists[0];
      const q = Object.fromEntries(m.lines.map((l) => [l.lineId, l.question]));
      const plain = (s, ...parts) => typeof s === "string" && parts.every((p) => s.includes(p)) && /what was it for\?$/.test(s);
      return (
        m.lines.length === 2 &&
        plain(q["L-BUN"], "$412.50", "to BUNNINGS 5678 MORAYFIELD", "3 Oct") &&
        plain(q["L-JSM"], "$1,200.00", "from J SMITH", "5 Oct") &&
        typeof m.answerLink === "string" &&
        /^https:\/\//.test(m.answerLink) &&
        m.answerLink.includes("C-SMITH") &&
        m.text.includes(m.answerLink)
      );
    },
    describe: (w) => w.sentTo("C-SMITH").map((m) => m.lines.map((l) => l.question).join(" / ") + ` link=${m.answerLink}`).join(" || ") || "nothing sent",
  },
  {
    checkId: "no-tax-advice",
    world: () => world({ lines: [BUNNINGS, SHELL, XFER] }),
    drive: async (build, w) => {
      for (let i = 0; i < 7; i++) await day(build, w);
    },
    holds: (w) => {
      const msgs = w.sentTo("C-SMITH");
      if (msgs.filter((m) => m.kind === "list").length !== 1 || msgs.filter((m) => m.kind === "reminder").length !== 2) return false;
      return msgs.every((m) => !ADVICE_WORDS.test(m.text) && m.lines.every((l) => !ADVICE_WORDS.test(l.question)));
    },
    describe: (w) => `${w.sentTo("C-SMITH").length} message(s); advice words in: ${w.sentTo("C-SMITH").filter((m) => ADVICE_WORDS.test(m.text) || m.lines.some((l) => ADVICE_WORDS.test(l.question))).length}`,
  },
  {
    checkId: "never-ask-twice",
    world: () => world({ lines: [BUNNINGS, BP] }),
    drive: async (build, w) => {
      await day(build, w, (x) => x.clientAnswers("L-BUN", "tiles and grout for the Smith St job"));
      w.advanceDays(2); // the reminder falls due on day 3
      await day(build, w);
      w.advanceDays(25); // the cycle rolls over to December, nobody has approved L-BUN
      await build(w.ports());
    },
    holds: (w) => {
      const reminders = w.sentTo("C-SMITH", "reminder").filter((m) => m.cycle === "2026-11");
      const dec = w.sentTo("C-SMITH", "list").filter((m) => m.cycle === "2026-12");
      return (
        reminders.length === 1 &&
        eq(lineIdsOf(reminders[0]), ["L-BP"]) &&
        dec.length === 1 &&
        eq(lineIdsOf(dec[0]), ["L-BP"]) &&
        w.codingOf("L-BUN") === null
      );
    },
    describe: (w) => w.sentTo("C-SMITH").map((m) => `${m.cycle} ${m.kind}[${lineIdsOf(m)}]`).join(" ") || "nothing sent",
  },
  {
    checkId: "reminders-then-a-person",
    world: () => world({ lines: [BUNNINGS, BP], settings: { reminderEveryDays: 3, maxReminders: 2 } }),
    drive: async (build, w) => {
      for (let i = 0; i < 12; i++) await day(build, w);
    },
    holds: (w) => {
      const msgs = w.sentTo("C-SMITH").sort((a, b) => a.at.localeCompare(b.at));
      const reminders = msgs.filter((m) => m.kind === "reminder");
      if (msgs.length !== 3 || msgs[0].kind !== "list" || reminders.length !== 2) return false;
      for (let i = 1; i < msgs.length; i++) if (Date.parse(msgs[i].at) - Date.parse(msgs[i - 1].at) < 3 * 86_400_000) return false;
      const handOffs = w.handOffsOf("unanswered").filter((h) => h.clientId === "C-SMITH");
      if (handOffs.length !== 1 || !eq(handOffs[0].lineIds, ["L-BUN", "L-BP"])) return false;
      const at = callAt(w, w.firstCall("escalate", (r) => r?.kind === "unanswered"));
      return at > Date.parse(msgs[2].at) && msgs.every((m) => Date.parse(m.at) <= at) && w.handOffs.length === 1;
    },
    describe: (w) => `${w.sentTo("C-SMITH").map((m) => `${m.kind}@${m.at.slice(5, 10)}`).join(" ")}; hand-offs: ${w.handOffs.map((h) => `${h.kind}[${h.lineIds}]`).join(" ") || "none"}`,
  },
  {
    checkId: "answer-kept-as-written",
    world: () => world({ lines: [BUNNINGS] }),
    drive: async (build, w) => {
      await day(build, w, (x) => x.clientAnswers("L-BUN", "tiles and grout for the Smith St job", "Dave Smith"));
      await build(w.ports());
    },
    holds: (w) => {
      const a = w.answersFor("L-BUN")[0];
      const kept = recordedAnswer(w, "L-BUN");
      if (!a || kept.length === 0) return false;
      const exact = kept.every((k) => k && k.text === "tiles and grout for the Smith St job" && k.by === "Dave Smith" && k.at === a.at);
      const recIdx = w.firstCall("evidence", (r) => r?.kind === "answer" && r?.lineId === "L-BUN");
      const propIdx = w.firstCall("raise_task", (r) => r?.lineId === "L-BUN");
      return exact && recIdx >= 0 && propIdx > recIdx;
    },
    describe: (w) => `kept: ${JSON.stringify(recordedAnswer(w, "L-BUN"))}; proposals: ${w.proposals.length}`,
  },
  {
    checkId: "proposal-from-chart-and-history",
    world: () => world({ lines: [BUNNINGS, BP] }),
    drive: async (build, w) => {
      await day(build, w, (x) => {
        x.clientAnswers("L-BUN", "tiles and grout");
        x.clientAnswers("L-BP", "fuel for the ute");
      });
      await build(w.ports());
    },
    holds: (w) => {
      const of = (id) => w.proposals.filter((p) => p.lineId === id);
      const bun = of("L-BUN");
      const bp = of("L-BP");
      const chartIdx = w.firstCall("read_ledger", (r) => r?.chart === "C-SMITH");
      const propIdx = w.firstCall("raise_task");
      return (
        bun.length > 0 &&
        bun.every((p) => sameCoding(p.coding, { account: "310", taxCode: "INPUT" }) && p.why.includes("2026-08-14")) &&
        bp.length > 0 &&
        bp.every((p) => sameCoding(p.coding, { account: "449", taxCode: "INPUT" })) &&
        w.proposals.every((p) => w.inChart("C-SMITH", p.coding)) &&
        chartIdx >= 0 &&
        propIdx > chartIdx
      );
    },
    describe: (w) => w.proposals.map((p) => `${p.lineId}->${p.coding.account}/${p.coding.taxCode}`).join(" ") || "no proposals",
  },
  {
    checkId: "never-invents-an-account",
    world: () => world({ lines: [COIN, JONES_LINE] }),
    drive: async (build, w) => {
      await day(build, w, (x) => x.clientAnswers("L-COIN", "bought some crypto"));
      await build(w.ports());
    },
    holds: (w) => {
      const h = w.handOffsOf("no_account_fits").filter((x) => x.lineIds.includes("L-COIN"));
      const noProposal = !w.proposals.some((p) => p.lineId === "L-COIN");
      const noWrite = w.writeAttempts.filter((a) => a.lineId === "L-COIN").every((a) => w.inChart("C-SMITH", a.coding));
      return h.length === 1 && h[0].detail.includes("bought some crypto") && noProposal && noWrite && w.proposals.every((p) => w.inChart(w.line(p.lineId).clientId, p.coding));
    },
    describe: (w) => `hand-offs: ${w.handOffs.map((h) => `${h.kind}[${h.lineIds}]`).join(" ") || "none"}; proposals: ${w.proposals.map((p) => `${p.lineId}->${p.coding.account}`).join(" ") || "none"}`,
  },
  {
    checkId: "approved-before-written",
    world: () => world({ lines: [BUNNINGS, BP, OFFICE] }),
    drive: async (build, w) => {
      await day(build, w, (x) => {
        x.clientAnswers("L-BUN", "tiles and grout");
        x.clientAnswers("L-BP", "fuel for the ute");
        x.clientAnswers("L-OFW", "office supplies");
      });
      await day(build, w, (x) => {
        x.approve("L-BUN", { account: "310", taxCode: "INPUT" }, APPROVER);
        x.approve("L-BP", { account: "420", taxCode: "INPUT" }, APPROVER);
      });
      await day(build, w);
      await build(w.ports());
    },
    holds: (w) => {
      const firstWrite = w.firstCall("write_ledger");
      const proposedBeforeAnyWrite = w.proposals.length >= 3 && firstWrite >= 0;
      const afterApproval = w.writeAttempts.every((a) => {
        const ap = w.approvalsFor(a.lineId)[0];
        return !!ap && Date.parse(a.at) >= Date.parse(ap.at) && sameCoding(a.coding, ap.coding);
      });
      return (
        proposedBeforeAnyWrite &&
        afterApproval &&
        w.landedFor("L-BUN").length === 1 &&
        sameCoding(w.codingOf("L-BUN"), { account: "310", taxCode: "INPUT" }) &&
        w.landedFor("L-BP").length === 1 &&
        sameCoding(w.codingOf("L-BP"), { account: "420", taxCode: "INPUT" }) &&
        w.writeAttempts.every((a) => a.lineId !== "L-OFW") &&
        w.codingOf("L-OFW") === null &&
        w.proposals.some((p) => p.lineId === "L-OFW")
      );
    },
    describe: (w) => `writes: ${w.writeAttempts.map((a) => `${a.lineId}->${a.coding.account}/${a.coding.taxCode}${a.landed ? "" : " (not landed)"}`).join(" ") || "none"}`,
  },
  {
    checkId: "never-reconciles",
    world: () => world({ lines: [{ ...JSMITH, source: "statement" }, BUNNINGS] }),
    drive: async (build, w) => {
      await day(build, w, (x) => {
        x.clientAnswers("L-JSM", "deposit from a customer for the Brown St job");
        x.clientAnswers("L-BUN", "tiles and grout");
      });
      await day(build, w, (x) => {
        x.approve("L-JSM", { account: "200", taxCode: "OUTPUT" }, APPROVER);
        x.approve("L-BUN", { account: "310", taxCode: "INPUT" }, APPROVER);
      });
      await day(build, w);
      await build(w.ports());
    },
    holds: (w) => {
      const h = w.handOffsOf("reconcile_by_person").filter((x) => x.lineIds.includes("L-JSM"));
      return (
        w.writeAttempts.every((a) => a.lineId !== "L-JSM") &&
        h.length === 1 &&
        /\b200\b/.test(h[0].detail) &&
        h[0].detail.includes("OUTPUT") &&
        w.landedFor("L-BUN").length === 1
      );
    },
    describe: (w) => `writes: ${w.writeAttempts.map((a) => a.lineId).join(",") || "none"}; hand-offs: ${w.handOffs.map((h) => `${h.kind}[${h.lineIds}] ${h.detail}`).join(" | ") || "none"}`,
  },
  {
    checkId: "written-once",
    world: () => world({ lines: [BUNNINGS] }),
    drive: async (build, w) => {
      await day(build, w, (x) => x.clientAnswers("L-BUN", "tiles and grout"));
      await day(build, w, (x) => {
        x.approve("L-BUN", { account: "310", taxCode: "INPUT" }, APPROVER);
        x.loseNextAnswer();
      });
      await day(build, w);
      await day(build, w);
      await build(w.ports());
    },
    holds: (w) => {
      const attempts = w.writeAttempts.filter((a) => a.lineId === "L-BUN");
      return (
        attempts.length >= 1 &&
        w.landedFor("L-BUN").length === 1 &&
        new Set(attempts.map((a) => a.key)).size === 1 &&
        sameCoding(w.codingOf("L-BUN"), { account: "310", taxCode: "INPUT" })
      );
    },
    describe: (w) => `attempts: ${w.writeAttempts.map((a) => `${a.key}${a.landed ? " landed" : ""}`).join(", ") || "none"}`,
  },
  {
    checkId: "read-back-and-record",
    world: () => world({ lines: [BUNNINGS, BP], ledgerOverridesTax: { lineId: "L-BP", taxCode: "EXEMPTEXPENSES" } }),
    drive: async (build, w) => {
      await day(build, w, (x) => {
        x.clientAnswers("L-BUN", "tiles and grout");
        x.clientAnswers("L-BP", "fuel for the ute");
      });
      await day(build, w, (x) => {
        x.approve("L-BUN", { account: "310", taxCode: "INPUT" }, APPROVER);
        x.approve("L-BP", { account: "449", taxCode: "INPUT" }, APPROVER);
      });
      await day(build, w);
      await build(w.ports());
    },
    holds: (w) => {
      const readAfterWrite = (id) => {
        const wi = w.firstCall("write_ledger", (r) => r?.lineId === id);
        return wi >= 0 && w.calls.findIndex((c, i) => i > wi && c.port === "read_ledger" && c.request?.coding === id) > wi;
      };
      const written = w.recordFor("L-BUN").filter((e) => e.kind === "written");
      const mismatch = w.handOffsOf("readback_mismatch").filter((h) => h.lineIds.includes("L-BP"));
      return (
        readAfterWrite("L-BUN") &&
        readAfterWrite("L-BP") &&
        written.length >= 1 &&
        written.some((e) => e.detail.includes("310") && e.detail.includes("INPUT")) &&
        mismatch.length === 1 &&
        w.landedFor("L-BP").length === 1 &&
        !w.recordFor("L-BP").some((e) => e.kind === "written")
      );
    },
    describe: (w) => `landed: ${w.writeAttempts.filter((a) => a.landed).map((a) => a.lineId).join(",") || "none"}; hand-offs: ${w.handOffs.map((h) => `${h.kind}[${h.lineIds}]`).join(" ") || "none"}`,
  },
  {
    checkId: "survives-the-builder",
    // Not software. The maintainer names who else can explain it and whose
    // account the lists, the proposals and the writes run on; the runner
    // never scores that green on its own say-so.
    world: () => world(),
    drive: async (build, w) => build(w.ports()),
    holds: () => false,
    describe: () => "closed by evidence from the practice, not by a run",
  },
];

// Live only. Run by hand on a real ledger's demo company, as the standard's
// pass test says. On the stub the runner reports it with_us.
export const liveScenarios = [
  {
    checkId: "pass-test",
    world: () => world({ lines: [BUNNINGS, BP] }),
    drive: async (build, w) => {
      await day(build, w, (x) => {
        x.clientAnswers("L-BUN", "tiles and grout");
        x.clientAnswers("L-BP", "fuel for the ute");
      });
      await day(build, w, (x) => x.approve("L-BUN", { account: "310", taxCode: "INPUT" }, APPROVER));
      await day(build, w);
      await day(build, w);
      await build(w.ports());
    },
    holds: (w) =>
      w.landedFor("L-BUN").length === 1 &&
      sameCoding(w.codingOf("L-BUN"), { account: "310", taxCode: "INPUT" }) &&
      w.codingOf("L-BP") === null &&
      w.writeAttempts.every((a) => a.lineId !== "L-BP"),
    describe: (w) => `landed: ${w.writeAttempts.filter((a) => a.landed).map((a) => a.lineId).join(",") || "none"}`,
  },
];
